solution.sanitized:
def undo_journal(events):
    values, history = {}, []
    for event in events:
        if event[0] == "add":
            _, key, delta = event
            values[key] = values.get(key, 0) + delta
            history.append((key, delta))
        elif event == ("undo",):
            if not history:
                raise ValueError("empty history")
            key, delta = history.pop()
            values[key] -= delta
        else:
            raise ValueError("event")
    return values

